def dense_layer_forward(inputs: list[float], weights: list[list[float]], biases: list[float]) -> list[float]:
    outputs = []
    for neuron_w, b in zip(weights, biases):
        z = sum(w * x for w, x in zip(neuron_w, inputs)) + b
        outputs.append(max(0.0, z))
    return outputs
